const data = $input.first().json;
const applicantType = data.applicant_type;

const checklists = {
  Individual: [
    { doc_type: 'photo_id', label: 'Photo ID (passport or driver licence)', required: true, category: 'identity' },
    { doc_type: 'proof_of_address', label: 'Proof of address (utility bill or bank statement)', required: true, category: 'identity' },
    { doc_type: 'cv_resume', label: 'CV / Resume', required: true, category: 'cv' },
    { doc_type: 'qualifications', label: 'Qualifications certificates', required: true, category: 'cv' },
    { doc_type: 'existing_licence_docs', label: 'Existing licence documents (if applicable)', required: false, category: 'licence' }
  ],
  Corporate: [
    { doc_type: 'company_extract', label: 'Company extract (auto-fetched from ASIC when available)', required: true, category: 'corporate' },
    { doc_type: 'ar_car_application_form', label: 'Completed AR / CAR application form', required: true, category: 'corporate' },
    { doc_type: 'director_shareholder_list', label: 'Director and shareholder list', required: true, category: 'corporate' },
    { doc_type: 'cv_resume', label: 'CV for key individual(s)', required: true, category: 'cv' },
    { doc_type: 'qualifications', label: 'Qualifications certificates', required: true, category: 'cv' },
    { doc_type: 'director_id', label: 'Photo ID for each director', required: true, category: 'identity' },
    { doc_type: 'beneficial_owner_id', label: 'Photo ID for each beneficial owner >=25%', required: true, category: 'identity' },
    { doc_type: 'audited_financials', label: 'Last 3 years audited financials', required: true, category: 'financial' },
    { doc_type: 'proof_of_company_address', label: 'Proof of company address', required: true, category: 'corporate' }
  ],
  Fund: [
    { doc_type: 'investment_manager_docs', label: 'Investment Manager corporate documents', required: true, category: 'fund' },
    { doc_type: 'information_memorandum', label: 'Proposed Information Memorandum (draft acceptable)', required: true, category: 'fund' },
    { doc_type: 'investment_mandate', label: 'Investment mandate and strategy document', required: true, category: 'fund' },
    { doc_type: 'trust_deed', label: 'Trust deed / constitution draft', required: true, category: 'fund' },
    { doc_type: 'im_cv_track_record', label: "Investment manager's CV / track record", required: true, category: 'cv' },
    { doc_type: 'fund_administrator', label: 'Proposed fund administrator details', required: true, category: 'fund' },
    { doc_type: 'custodian_details', label: 'Proposed custodian details', required: true, category: 'fund' },
    { doc_type: 'auditor_details', label: 'Proposed auditor details', required: true, category: 'fund' },
    { doc_type: 'legal_advice', label: 'Legal advice on fund structure', required: false, category: 'legal' },
    { doc_type: 'service_provider_terms', label: 'Service provider proposals / term sheets', required: false, category: 'fund' },
    { doc_type: 'structure_chart', label: 'Organisational / structure chart', required: false, category: 'fund' },
    { doc_type: 'insurance_details', label: 'Insurance details (PI / cyber / asset-level where applicable)', required: false, category: 'legal' },
    { doc_type: 'tax_advice', label: 'Tax advice (mandatory for non-traditional asset classes)', required: false, category: 'legal' }
  ]
};

const checklist = checklists[applicantType] || checklists.Individual;
return [{ json: { ...data, checklist } }];

const caseData = $input.first().json;
const checklist = $('Build Checklist').first().json.checklist;
const uploadUrl = `${$env.UPLOAD_BASE_URL || 'https://upload.example.invalid'}/upload/${caseData.applicant_id}`;
const inboxEmail = $env.DOCUMENTS_INBOX_EMAIL || 'operator@example.invalid';

const required = checklist.filter(i => i.required);
const optional = checklist.filter(i => !i.required);

let html = '<ul>';
required.forEach(item => { html += `<li><strong>${item.label}</strong></li>`; });
html += '</ul>';
if (optional.length > 0) {
  html += '<p><em>The following are required only where applicable:</em></p><ul>';
  optional.forEach(item => { html += `<li>${item.label}</li>`; });
  html += '</ul>';
}

const emailBody = `<p>Hi ${caseData.primary_contact_name},</p>
<p>Thank you for your inquiry. To progress your application we need the following documents:</p>
${html}
<p><strong>How to send them — either option:</strong></p>
<ol>
  <li>Upload via our secure portal: <a href="${uploadUrl}">${uploadUrl}</a></li>
  <li>Reply to this email with the files attached, or email <a href="mailto:${inboxEmail}">${inboxEmail}</a></li>
</ol>
<p>Please include your applicant ID <strong>${caseData.applicant_id}</strong> in the subject line of any email you send.</p>
<p>You'll receive a confirmation as each file is received.</p>
<p>Regards,<br>Alpha Node Compliance Team</p>`;

return [{
  json: {
    ...caseData,
    upload_url: uploadUrl,
    email_subject: `Alpha Node — Document Checklist for ${caseData.applicant_id}`,
    email_body: emailBody
  }
}];
